-- Neu: Dateien laden (ALLY 41): Fassungen der Dateien und – nur bei /neu?datei=… – der Inhalt der angefragten Datei (skript, stil, schrift).
SELECT (SELECT coalesce(jsonb_object_agg(name, fassung), '{}'::jsonb) FROM ally_webapp_dateien) AS fassungen,
  (SELECT inhalt FROM ally_webapp_dateien WHERE name = CASE $1::text WHEN 'skript' THEN 'app.js' WHEN 'stil' THEN 'app.css' WHEN 'schrift' THEN 'schrift.css' END) AS inhalt;

