// Neu: Antwort (ALLY 41, Weg B): Dateien der neuen Web-App (/neu?datei=skript|stil|schrift); /neu ohne Datei leitet auf die normale Adresse weiter (16:13). Die gebauten Dateien liegen in ally_webapp_dateien
// (ALLY 42 holt sie aus dem Repo, ALLY 43 die Schrift des Firmendesigns – so lädt der Browser nichts von Google). Mit passender Fassung (?v=) ein Jahr zwischenspeichern, sonst kurz. Basis wie ALLY 20: „/“ auf der eigenen Adresse.
const W = $('Hülle').first().json || {};
const q = W.query || {};
const D = $input.first().json || {};
const basis = String(((W.headers || {})['x-oberflaeche-basis']) ?? '') === '/' ? '/' : '/webhook/app/';
const F = D.fassungen && typeof D.fassungen === 'object' ? D.fassungen : {};
const art = ['skript', 'stil', 'schrift'].includes(String(q.datei || '')) ? String(q.datei) : '';
const DATEI = { skript: 'app.js', stil: 'app.css', schrift: 'schrift.css' };
// Schrift nur einbinden, wenn sie wirklich geladen ist (sonst Systemschrift)
const schrift = F['schrift.css'] && !['leer', 'fehler', 'laedt'].includes(String(F['schrift.css'])) ? String(F['schrift.css']) : '';
const esc = t => String(t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
let status = 200, typ = '', text = '', cache = 'no-store';
if (art) {
  const name = DATEI[art];
  if (typeof D.inhalt === 'string' && D.inhalt) {
    typ = art === 'skript' ? 'text/javascript; charset=utf-8' : 'text/css; charset=utf-8'; text = D.inhalt;
    cache = String(q.v || '') && String(q.v) === String(F[name] || '') ? 'public, max-age=31536000, immutable' : 'public, max-age=300';
  } else { status = 404; typ = 'text/plain; charset=utf-8'; text = 'Nicht gefunden'; }
} else {
  // Stefan 23.10.2026, 16:13 („keinen Test im Test“): /neu ist keine eigene Adresse mehr, nur noch Weiterleitung auf die normale Adresse mit denselben Parametern
  // (Lesezeichen und verschickte Links funktionieren weiter). Die Hülle liefert ALLY 20 („Neu: Hülle“) unter /?seite=…
  typ = 'text/html; charset=utf-8';
  const wurzel = basis === '/' ? '/' : '/webhook/app';
  const suche = Object.keys(q).filter(k => /^[a-z0-9_]{1,30}$/.test(k)).slice(0, 25)
    .map(k => encodeURIComponent(k) + '=' + encodeURIComponent(String(Array.isArray(q[k]) ? q[k][0] : q[k]).slice(0, 200))).join('&');
  const ziel = wurzel + (suche ? '?' + suche : '?seite=verkaufsberichte');
  text = '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=' + esc(ziel) + '"><title>Ally</title></head>' +
    '<body><p><a href="' + esc(ziel) + '">Weiter zu Ally</a></p><script>location.replace(' + JSON.stringify(ziel).replace(/</g, '\\u003c') + ');</script></body></html>';
}
return [{ json: { status, typ, cache }, binary: { datei: { data: Buffer.from(text, 'utf8').toString('base64'), mimeType: typ.split(';')[0], fileName: art ? DATEI[art] : 'index.html' } } }];

// API lesen (ALLY 41, Knoten „Anfrage lesen“): Sitzung aus dem Cookie ally_sitzung2, geprüfte Parameter. Gleicher Code im Ablauf und im lokalen Prüfserver.
// Eingabe: Webhook-Item { headers, query }. Ausgabe: { werte: [token, seite, parameterJson, verlaufJson], seite, ordner, projekte }.
const j = $input.first().json || {};
const h = j.headers || {};
const q = j.query || {};
const kekse = String(h.cookie || '').split(';').map(x => x.trim());
const roh = (kekse.find(x => x.startsWith('ally_sitzung2=')) || '').slice('ally_sitzung2='.length);
const token = /^[0-9a-f]{64}$/.test(roh) ? roh : '';
// Stufe 2a (Migration 105): auch die neuen Einstellungen (Übersicht, Verbindungen)
// Migration 127: „kosten“ = nur die Kosten einer Funktion (kf) bzw. aller Funktionen (kf = alle) für Baukasten-Seiten und Startseite (E11)
// Migration 136 (Stefan 24.10.2026): Monatsberichte im Aufbau der Verkaufsberichte (Liste, Papierkorb, neuer Bericht, Bericht)
const seite = ['verkaufsberichte', 'shops', 'einstellungen', 'kosten', 'monatsbericht'].includes(String(q.seite || '')) ? String(q.seite) : 'verkaufsberichte';
let P = {};
try { const x = JSON.parse(String(q.p || '{}')); if (x && typeof x === 'object' && !Array.isArray(x)) P = x; } catch (e) { P = {}; }
const txt = v => { const t = String(v ?? '').trim(); return t.length <= 300 && !/[\x00-\x1f\x7f]/.test(t) ? t : ''; };
const f = {};
if (/^[0-9]{1,9}$/.test(String(P.bericht || ''))) f.bericht = String(P.bericht);
if (String(P.archiv || '') === '1') f.archiv = '1';
if (f.bericht && String(P.produkte || '') === '1') {
  f.produkte = '1'; f.q = txt(P.q).slice(0, 100);
  if (['ACTIVE', 'DRAFT', 'ARCHIVED', 'gewaehlt'].includes(String(P.pst || ''))) f.pst = String(P.pst);
  if (/^[0-9]{1,4}$/.test(String(P.ps || ''))) f.ps = String(P.ps);
  // Migration 108: Haken der offenen Produktliste (gewählte zuerst, auch beim Blättern); nur Nummern
  if (typeof P.vorne === 'string' && P.vorne.length <= 4000) f.vorne = P.vorne.split(',').filter(x => /^[0-9]{1,18}$/.test(x)).slice(0, 250).join(',');
}
if (f.bericht && /^[0-9]{1,18}$/.test(String(P.mail || ''))) f.mail = String(P.mail);
// Stufe 2b (Migration 120): Seite eines Postfachs in den Einstellungen (Adresse geprüft, Rechte prüft webapp_postfach_web)
if (seite === 'einstellungen' && /^[^\s@<>"']{1,200}@[^\s@<>"']{1,100}$/.test(String(P.postfach || ''))) f.postfach = String(P.postfach).toLowerCase();
if (seite === 'einstellungen' && String(P.bereich || '') === 'meine-postfaecher') f.meine = '1';
if (seite === 'kosten' && /^[a-z][a-z0-9-]{1,39}$/.test(String(P.kf || ''))) f.kf = String(P.kf);
// und (Stefan 24.10.2026, 12:23) die Übersicht: Zeitraum je Bericht wie auf der Berichtsseite, mit Daten. Ein Abruf für alle Zeilen.
// Nicht im Papierkorb.
if (seite === 'monatsbericht' && String(P.bericht || '') === 'neu') f.neu = '1';
const projekte = seite === 'monatsbericht' && String(P.archiv || '') !== '1';
// (Stefan 23.10.2026, 14:46/14:49/15:55; keine eigene Verlaufsseite mehr)
const v = f.bericht && seite === 'verkaufsberichte' ? { bericht: f.bericht, je_seite: '10', zr: /^(alle|[0-9]{4}|[0-9]{4}-(0[1-9]|1[0-2]))$/.test(String(P.zr || '')) ? String(P.zr) : 'alle',
  ps: /^[0-9]{1,5}$/.test(String(P.ps || '')) ? String(P.ps) : '1',
  so: ['alt', 'anlass'].includes(String(P.so || '')) ? String(P.so) : 'neu' } : null;  // Migration 103: Sortierung über alle Einträge
const ordner = { an: seite === 'verkaufsberichte' && !!f.bericht && String(P.ordner || '') === '1', pfad: txt(P.op).replace(/^\/+|\/+$/g, '') };
// Glocke (Stefan 23.10.2026, 16:45): bn = geöffnete Benachrichtigung; ally_ui_eingang markiert nur eigene als gelesen (wie ALLY 20)
const bn = /^[0-9]{1,18}$/.test(String(P.bn || '')) ? String(P.bn) : '0';  // nie leer (Ersetzung in n8n)
return [{ json: { token, seite, ordner, projekte, werte: [token, seite, JSON.stringify(f), v ? JSON.stringify(v) : '{}', bn] } }];

// und der Speicherort das kann. SPEICHER 1 prüft Recht und Pfad noch einmal (speicher_ordner_auftrag, bereich berichte).
const A = $('Anfrage lesen').first().json;
const D = $('Daten laden').first().json || {};
const R = D.daten_vb && D.daten_vb.ok === true ? D.daten_vb : null;
const lesen = !!(A.ordner && A.ordner.an && R && R.bericht && R.ablage && R.ablage.browser === true);
return [{ json: { lesen, aktion: 'ordner_liste', token: String(A.token || ''), daten: { bereich: 'berichte', pfad: lesen ? String(A.ordner.pfad || '') : '' } } }];

// API Antwort (ALLY 41): JSON für die Web-App. Ordner-Inhalt kommt von SPEICHER 1 (nur beim Ordner-Browser).
const D = $('Daten laden').first().json || {};
const O = $('Ordner lesen (SPEICHER 1)').isExecuted ? ($('Ordner lesen (SPEICHER 1)').first().json || null) : null;
const A = $('Anfrage lesen').first().json || {};
const rahmen = D.rahmen && typeof D.rahmen === 'object' ? D.rahmen : { angemeldet: false };
// V1 (Prüfung 136): nur wenn monatsbericht_web das Recht bestätigt hat (ok = true); sonst weder Abruf noch Liste
const mbOk = !!(D.daten_mb && D.daten_mb.ok === true);
const PK = null;
const pkFehler = PK && (PK.error || !Array.isArray(PK.eintraege)) ? String((PK.error && (PK.error.message || PK.error)) || 'Die Projektliste konnte nicht geladen werden.') : '';
const projekte = PK && !pkFehler ? PK.eintraege.filter(p => p && p.record_state === 'active' && /^[0-9]{1,12}$/.test(String(p.id))).map(p => ({ id: String(p.id), name: String(p.name || ''),
  kunde_id: String(p.company_id ?? ''), start: p.start_date ? String(p.start_date).slice(0, 10) : '', ende: p.end_date ? String(p.end_date).slice(0, 10) : '', angelegt: p.created_at ? String(p.created_at).slice(0, 10) : '',
  budget_art: String(p.budget_type || ''), budget_geld: p.budget_money ?? null, budget_zeit: p.budget_time ?? null })) : null;
const daten = A.seite === 'monatsbericht' ? (D.daten_mb ? Object.assign({}, D.daten_mb, mbOk && A.projekte ? { projekte, projekte_fehler: pkFehler } : {}) : null) : A.seite === 'shops' ? { sh: D.sh || null } : A.seite === 'einstellungen' ? (D.ei ? Object.assign({}, D.ei, D.ei_pakete ? { pakete: D.ei_pakete } : {}, D.pf ? { pf: D.pf } : {}, D.mp ? { mp: D.mp } : {}) : null) : (D.daten_vb || null);
return [{ json: { rahmen, cd: D.cd || null, daten, verlauf: D.verlauf || null, ordner: O, kosten: D.kosten || null } }];

