-- Migration 210 (Stefan 06.11.2026 „Name“): Karte der Kennungen für die selbst gebauten Seiten der Web-App (nur mit Merker adressen_pfade; Rechte prüft ally_ui_kennungen_karte)
-- Verlinkt: die Nummern (id, bericht) in den Daten der Seite, als Objekte der Seite (Shops: Verkaufsberichte)
SELECT CASE WHEN $1::text <> '' AND ally_ui_pfade_an() THEN ally_ui_kennungen_karte($1::text, NULL, $2::jsonb) END AS karte;

