// Migration 210 (Stefan 06.11.2026 „Name“): Antwort der API mit der Karte der Kennungen (nur für Verkaufsberichte, Monatsberichte, Shops; sonst unverändert)
const j = Object.assign({}, $('API-Antwort').first().json || {});
const K = ($input.first().json || {}).karte;
if (Array.isArray(K) && K.length) j.kennungen = K;
return [{ json: j }];
